#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
Idempotency-kulcs minden üzenetre — retry-nál ne duplikálódjon.

This module implements an idempotency-key based deduplication layer for the
A2A Mesh messaging system. Every message carries an idempotency key; if a
message with the same key has already been processed (within its TTL window),
the duplicate is detected and not re-delivered to handlers.

Features:
  - Per-message idempotency key (auto-generated if not provided)
  - TTL-based expiry of seen keys (memory bounded)
  - Thread-safe deduplication store
  - Drop-in MessageBus wrapper that filters duplicates
  - Dead-letter callback for duplicate detection (observability)
  - CLI demo / self-test

Run from repo root:
    python a2a_mesh/idempotency.py
"""

from __future__ import annotations

import hashlib
import json
import threading
import time
import uuid
from dataclasses import dataclass, field, asdict
from typing import Any, Callable, Dict, Optional


# ---------------------------------------------------------------------------
# Data model
# ---------------------------------------------------------------------------

@dataclass
class MeshMessage:
    """A single message on the A2A Mesh."""
    topic: str
    payload: Any
    sender: str
    idempotency_key: str = ""
    timestamp: float = field(default_factory=time.time)
    message_id: str = field(default_factory=lambda: str(uuid.uuid4()))

    def __post_init__(self) -> None:
        if not self.idempotency_key:
            # Deterministic key derived from topic + payload + sender so that
            # identical retries produce the same key even if the caller forgot
            # to set one explicitly.
            raw = f"{self.topic}|{self.sender}|{json.dumps(self.payload, sort_keys=True, default=str)}"
            self.idempotency_key = hashlib.sha256(raw.encode("utf-8")).hexdigest()[:32]

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "MeshMessage":
        return cls(**d)


# ---------------------------------------------------------------------------
# Idempotency store
# ---------------------------------------------------------------------------

class IdempotencyStore:
    """
    Thread-safe store that remembers which idempotency keys have been seen
    within a configurable TTL window.

    `check_and_mark(key)` returns True if the key is NEW (first sighting) and
    records it. Returns False if the key was already seen (duplicate).
    """

    def __init__(self, ttl_seconds: float = 3600.0, max_entries: int = 100_000) -> None:
        self.ttl_seconds = ttl_seconds
        self.max_entries = max_entries
        self._seen: Dict[str, float] = {}  # key -> expiry timestamp
        self._lock = threading.Lock()

    def _purge_expired(self, now: Optional[float] = None) -> None:
        """Remove expired entries. Caller must hold the lock."""
        now = now if now is not None else time.time()
        expired = [k for k, exp in self._seen.items() if exp <= now]
        for k in expired:
            del self._seen[k]

    def check_and_mark(self, key: str) -> bool:
        """
        Atomically check whether `key` is new.
        Returns True  -> first time seen, now marked.
        Returns False -> duplicate, already processed within TTL.
        """
        if not key:
            # Empty key: treat as always-new (no dedup possible).
            return True
        now = time.time()
        with self._lock:
            self._purge_expired(now)
            if key in self._seen:
                # Refresh TTL on duplicate sighting so active keys stay alive.
                self._seen[key] = now + self.ttl_seconds
                return False
            # Enforce max-entries cap (evict oldest by expiry).
            if len(self._seen) >= self.max_entries:
                oldest_key = min(self._seen, key=self._seen.get)  # type: ignore[arg-type]
                del self._seen[oldest_key]
            self._seen[key] = now + self.ttl_seconds
            return True

    def has(self, key: str) -> bool:
        """Non-mutating check: has this key been seen (and not expired)?"""
        if not key:
            return False
        now = time.time()
        with self._lock:
            self._purge_expired(now)
            return key in self._seen

    def clear(self) -> None:
        with self._lock:
            self._seen.clear()

    def size(self) -> int:
        now = time.time()
        with self._lock:
            self._purge_expired(now)
            return len(self._seen)


# ---------------------------------------------------------------------------
# Message bus with idempotency
# ---------------------------------------------------------------------------

DuplicateCallback = Callable[[MeshMessage], None]


class IdempotentMessageBus:
    """
    A topic-based pub/sub message bus that enforces idempotency.

    Subscribers register for topics (exact match or wildcard '*').
    Each published message is checked against the IdempotencyStore before
    being delivered. Duplicates are dropped and optionally reported via a
    `on_duplicate` callback (useful for metrics / dead-letter logging).
    """

    def __init__(
        self,
        store: Optional[IdempotencyStore] = None,
        on_duplicate: Optional[DuplicateCallback] = None,
    ) -> None:
        self.store = store or IdempotencyStore()
        self.on_duplicate = on_duplicate
        self._subscribers: Dict[str, list[Callable[[MeshMessage], None]]] = {}
        self._lock = threading.Lock()
        # stats
        self.stats = {
            "published": 0,
            "delivered": 0,
            "duplicates_dropped": 0,
        }

    # -- subscription -------------------------------------------------------

    def subscribe(self, topic: str, handler: Callable[[MeshMessage], None]) -> None:
        with self._lock:
            self._subscribers.setdefault(topic, []).append(handler)

    def unsubscribe(self, topic: str, handler: Callable[[MeshMessage], None]) -> None:
        with self._lock:
            subs = self._subscribers.get(topic, [])
            if handler in subs:
                subs.remove(handler)

    # -- publishing ---------------------------------------------------------

    def publish(self, message: MeshMessage) -> bool:
        """
        Publish a message. Returns True if it was delivered to at least one
        subscriber, False if it was dropped as a duplicate (or had no
        subscribers).
        """
        self.stats["published"] += 1

        if not self.store.check_and_mark(message.idempotency_key):
            self.stats["duplicates_dropped"] += 1
            if self.on_duplicate:
                try:
                    self.on_duplicate(message)
                except Exception:
                    pass
            return False

        delivered = False
        with self._lock:
            handlers = list(self._subscribers.get(message.topic, []))
            handlers += list(self._subscribers.get("*", []))

        for handler in handlers:
            try:
                handler(message)
                delivered = True
            except Exception as exc:  # noqa: BLE001
                # Handler failure does NOT un-mark the key: the message was
                # *seen* and a retry with the same key will be dropped. This
                # is intentional — use a distinct key for genuine replays.
                print(f"[bus] handler error for {message.message_id}: {exc}")

        if delivered:
            self.stats["delivered"] += 1
        return delivered

    def publish_raw(
        self,
        topic: str,
        payload: Any,
        sender: str,
        idempotency_key: str = "",
    ) -> bool:
        """Convenience wrapper that builds a MeshMessage and publishes it."""
        msg = MeshMessage(
            topic=topic,
            payload=payload,
            sender=sender,
            idempotency_key=idempotency_key,
        )
        return self.publish(msg)


# ---------------------------------------------------------------------------
# Demo / self-test
# ---------------------------------------------------------------------------

def _demo() -> None:
    print("=" * 64)
    print("A2A Mesh — Idempotency Key Demo")
    print("=" * 64)

    received: list[MeshMessage] = []
    duplicates: list[MeshMessage] = []

    bus = IdempotentMessageBus(
        ttl_seconds=60.0,
        on_duplicate=lambda m: duplicates.append(m),
    )

    def handler(msg: MeshMessage) -> None:
        received.append(msg)
        print(f"  [handler] topic={msg.topic!r} payload={msg.payload!r} "
              f"key={msg.idempotency_key[:12]}…")

    bus.subscribe("tasks", handler)
    bus.subscribe("*", handler)  # wildcard

    # --- Case 1: explicit idempotency key, retried twice -----------------
    print("\n[1] Explicit key, same message published 3× (2 retries):")
    key1 = "job-42-run-001"
    for i in range(3):
        ok = bus.publish_raw("tasks", {"job": 42, "step": i}, "agent-A", key1)
        print(f"   attempt {i+1}: delivered={ok}")

    # --- Case 2: auto-generated key from content -------------------------
    print("\n[2] Auto-generated key (content-based), identical payload 2×:")
    bus.publish_raw("tasks", {"job": 99}, "agent-B")
    bus.publish_raw("tasks", {"job": 99}, "agent-B")  # same content → same key → dropped

    # --- Case 3: different content → different key → both delivered -----
    print("\n[3] Different payloads → different keys → both delivered:")
    bus.publish_raw("tasks", {"job": 100}, "agent-B")
    bus.publish_raw("tasks", {"job": 101}, "agent-B")

    # --- Case 4: same key but different topic → still dropped -----------
    print("\n[4] Same key, different topic → still dropped (key is global):")
    bus.publish_raw("events", {"x": 1}, "agent-C", idempotency_key="shared-key-7")
    bus.publish_raw("alerts", {"x": 1}, "agent-C", idempotency_key="shared-key-7")

    # --- Case 5: TTL expiry simulation -----------------------------------
    print("\n[5] TTL expiry — shrink TTL and verify key is forgotten:")
    bus.store.ttl_seconds = 0.05
    bus.publish_raw("tasks", {"job": 200}, "agent-D", idempotency_key="ephemeral-1")
    time.sleep(0.1)
    ok = bus.publish_raw("tasks", {"job": 200}, "agent-D", idempotency_key="ephemeral-1")
    print(f"   after TTL: delivered={ok} (expected True)")

    # --- Summary ----------------------------------------------------------
    print("\n" + "=" * 64)
    print("Summary")
    print("=" * 64)
    print(f"  Total published          : {bus.stats['published']}")
    print(f"  Delivered to handlers    : {bus.stats['delivered']}")
    print(f"  Duplicates dropped       : {bus.stats['duplicates_dropped']}")
    print(f"  Handler received count   : {len(received)}")
    print(f"  Duplicate callback count : {len(duplicates)}")
    print(f"  Store size (live keys)   : {bus.store.size()}")

    # Assertions (self-test)
    assert len(received) == 6, f"expected 6 deliveries, got {len(received)}"
    assert bus.stats["duplicates_dropped"] == 4, (
        f"expected 4 duplicates dropped, got {bus.stats['duplicates_dropped']}"
    )
    print("\n✅ All self-test assertions passed.")


if __name__ == "__main__":
    _demo()